 class eventclass_estudiantes  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeAdd"]=true;

		$this->events["BeforeEdit"]=true;

		$this->events["BeforeDelete"]=true;

		$this->events["BeforeQueryList"]=true;


	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$cedula     = trim($values["numero_cedula"]);
$matricula  = trim($values["matricula"]);
$usuario_id = intval($values["usuario_id"]);
$carrera_id = intval($values["carrera_id"]);

// 1. Validaciones obligatorias
if (empty($cedula)) {
    $message = "El número de cédula de identidad es obligatorio.";
    return false;
}

if ($carrera_id <= 0) {
    $message = "Debe asignar una carrera válida al estudiante.";
    return false;
}

if ($usuario_id <= 0) {
    $message = "Debe vincular una cuenta de usuario existente al estudiante.";
    return false;
}

// 2. Cédula única
$rsCed = DB::Query("SELECT id FROM estudiantes WHERE numero_cedula = " . db_prepare_string($cedula) . " LIMIT 1");
if ($rsCed->fetchAssoc()) {
    $message = "La cédula <strong>" . htmlspecialchars($cedula) . "</strong> ya pertenece a otro estudiante.";
    return false;
}

// 3. Usuario único
$rsUsr = DB::Query("SELECT id FROM estudiantes WHERE usuario_id = " . $usuario_id . " LIMIT 1");
if ($rsUsr->fetchAssoc()) {
    $message = "La cuenta de usuario seleccionada ya tiene un legajo de estudiante activo.";
    return false;
}

// 4. Autogenerar matrícula si viene vacía
if (empty($matricula)) {
    $rsCount = DB::Query("SELECT COUNT(*) AS total FROM estudiantes");
    $rowCount = $rsCount->fetchAssoc();
    $values["matricula"] = "UASS-" . date("Y") . "-" . str_pad(intval($rowCount["total"]) + 1, 4, "0", STR_PAD_LEFT);
} else {
    $rsMat = DB::Query("SELECT id FROM estudiantes WHERE matricula = " . db_prepare_string($matricula) . " LIMIT 1");
    if ($rsMat->fetchAssoc()) {
        $message = "El número de matrícula ya se encuentra asignado.";
        return false;
    }
}

// 5. Fecha de ingreso por defecto
if (empty($values["fecha_ingreso"])) {
    $values["fecha_ingreso"] = date("Y-m-d");
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, $where, &$oldvalues, &$keys, &$message, $inline, &$pageObject)
{

		$id_actual  = isset($keys["id"]) ? intval($keys["id"]) : 0;
$cedula     = trim($values["numero_cedula"]);
$matricula  = trim($values["matricula"]);
$usuario_id = intval($values["usuario_id"]);
$carrera_id = intval($values["carrera_id"]);

if (empty($cedula)) {
    $message = "El número de cédula de identidad es obligatorio.";
    return false;
}

if ($carrera_id <= 0) {
    $message = "Debe seleccionar una carrera.";
    return false;
}

$rsCed = DB::Query("SELECT id FROM estudiantes WHERE numero_cedula = " . db_prepare_string($cedula) . " AND id != " . $id_actual . " LIMIT 1");
if ($rsCed->fetchAssoc()) {
    $message = "La cédula ya pertenece a otro estudiante.";
    return false;
}

if (!empty($matricula)) {
    $rsMat = DB::Query("SELECT id FROM estudiantes WHERE matricula = " . db_prepare_string($matricula) . " AND id != " . $id_actual . " LIMIT 1");
    if ($rsMat->fetchAssoc()) {
        $message = "El número de matrícula ya pertenece a otro alumno.";
        return false;
    }
}

if ($usuario_id > 0) {
    $rsUsr = DB::Query("SELECT id FROM estudiantes WHERE usuario_id = " . $usuario_id . " AND id != " . $id_actual . " LIMIT 1");
    if ($rsUsr->fetchAssoc()) {
        $message = "El usuario seleccionado ya está asignado a otro estudiante.";
        return false;
    }
}

return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$est_id = intval($deleted_values["id"]);

// No borrar si tiene inscripciones
$rsIns = DB::Query("SELECT COUNT(*) AS total FROM inscripciones WHERE estudiante_id = " . $est_id);
$rIns = $rsIns->fetchAssoc();
if (intval($rIns["total"]) > 0) {
    $message = "No es posible eliminar al estudiante porque posee materias inscriptas en su historial académico.";
    return false;
}

// No borrar si tiene pagos o cuotas
$rsPag = DB::Query("SELECT COUNT(*) AS total FROM pagos WHERE estudiante_id = " . $est_id);
$rPag = $rsPag->fetchAssoc();
if (intval($rPag["total"]) > 0) {
    $message = "No es posible eliminar al estudiante porque posee registros de cuotas o aranceles en Tesorería.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		// RLS: Un alumno solo puede ver su propio registro
if ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "id = " . intval($_SESSION["estudiante_id"]));
}
// Docente: solo ve a los alumnos inscriptos en sus cátedras
elseif ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "id IN (SELECT DISTINCT i.estudiante_id FROM inscripciones i INNER JOIN cursos c ON c.id = i.curso_id WHERE c.profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



